    oh=(H-kh)//stride+1; ow=(W-kw)//stride+1
    c = x.unfold(2,kh,stride).unfold(3,kw,stride)
    return c.permute(0,2,3,1,4,5).reshape(N*oh*ow, C*kh*kw)

